{"content":""""Specification model: no joblab imports, SQL, UUIDs or production helpers.

Attempts are history entries rather than a mutable attempt counter. Readiness
is an event deadline. Retry delay is accumulated by doubling across failures.
"""
from copy import deepcopy


class Model:
    def __init__(self):
        self.now = 1000
        self.jobs = {}
        self.keys = {}

    def submit(self, label, payload, key, limit, backoff, due):
        if key is not None and key in self.keys:
            return self.keys[key]
        self.jobs[label] = dict(payload=deepcopy(payload), key=key, limit=limit,
                                base=backoff, delay=backoff, ready=due,
                                born=self.now, changed=self.now, state='pending',
                                history=[], result=None, error=None)
        if key is not None:
            self.keys[key] = label
        return label

    def eligible(self):
        return [label for label, j in self.jobs.items()
                if (j['state'] == 'pending' and j['ready'] <= self.now)
                or (j['state'] == 'running' and j['history'][-1]['end'] <= self.now
                    and len(j['history']) < j['limit'])]

    def live(self):
        return [label for label, j in self.jobs.items()
                if j['state'] == 'running' and self.now < j['history'][-1]['end']]

    def claim(self, label, duration):
        for j in self.jobs.values():
            if (j['state'] == 'running' and j['history'][-1]['end'] <= self.now
                    and len(j['history']) == j['limit']):
                j.update(state='failed', changed=self.now,
                         error='lease expired; attempts exhausted')
        if label is None:
            return
        j = self.jobs[label]
        j['history'].append({'end': self.now + duration})
        j.update(state='running', changed=self.now)
        # The retry delay is a property of this attempt, including expired ones.
        j['delay'] = j['base']
        for _ in j['history'][1:]:
            j['delay'] += j['delay']

    def finish(self, label, success, value):
        j = self.jobs[label]
        j['changed'] = self.now
        if success:
            j.update(state='succeeded', result=deepcopy(value), error=None)
        else:
            remaining = j['limit'] - len(j['history'])
            j.update(state='pending' if remaining else 'failed', error=value,
                     ready=self.now + (j['delay'] if remaining else 0))

    def cancel(self, label):
        j = self.jobs[label]
        j.update(state='cancelled', changed=self.now)

    def heartbeat(self, label, duration):
        j = self.jobs[label]
        if self.now + duration > j['history'][-1]['end']:
            j['history'][-1]['end'] = self.now + duration
        if self.now > j['changed']:
            j['changed'] = self.now

    def snapshot(self, label):
        j = self.jobs[label]
        return dict(payload=j['payload'], dedupe_key=j['key'], status=j['state'],
                    attempts=len(j['history']), max_attempts=j['limit'], backoff=j['base'],
                    available_at=j['ready'], created_at=j['born'], updated_at=j['changed'],
                    result=j['result'], error=j['error'],
                    lease_until=j['history'][-1]['end'] if j['state'] == 'running' else None)
