{"content":""""Seeded public-API differential harness; runnable for seed or trace replay."""
import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path
import random
import sys
import tempfile
import time
import unittest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from joblab import Queue, LeaseLost
from reference_model import Model

ARTIFACTS = ROOT / 'artifacts' / 'phase-04'


class Runner:
    def __init__(self, path):
        self.model = Model()
        self.path = path
        self.q = Queue(path, clock=lambda: self.model.now)
        self.ids = {}
        self.tokens = {}
        self.seen_tokens = set()
        self.old_tokens = []
        self.counts = Counter()
        self.probes = 0

    def check(self):
        rows = self.q.list()
        assert len(rows) == len(self.model.jobs), 'job count mismatch'
        reverse = {value: key for key, value in self.ids.items()}
        for row in rows:
            label = reverse[row['id']]
            expected = self.model.snapshot(label)
            actual = {key: row[key] for key in expected}
            assert actual == expected, (label, expected, actual)
            expected_token = self.tokens[label] if row['status'] == 'running' else None
            assert row['lease_token'] == expected_token, 'token changed unexpectedly'
            assert 0 <= row['attempts'] <= row['max_attempts']

    def apply(self, op):
        m = self.model
        kind = op['op']
        label = op.get('label')
        if kind == 'submit':
            expected = m.submit(label, op['payload'], op['key'], op['limit'], op['backoff'], op['due'])
            actual = self.q.submit(op['payload'], dedupe_key=op['key'], max_attempts=op['limit'],
                                   backoff=op['backoff'], available_at=op['due'])
            if expected in self.ids:
                assert actual['id'] == self.ids[expected], 'dedupe mismatch'
            else:
                assert actual['id'] not in self.ids.values(), 'ID collision'
                self.ids[expected] = actual['id']
        elif kind == 'claim':
            candidates = m.eligible()
            # ID is opaque: ties in documented priority may choose any tied member.
            if candidates:
                priority = min((m.jobs[x]['ready'], m.jobs[x]['born']) for x in candidates)
                allowed = [x for x in candidates if (m.jobs[x]['ready'], m.jobs[x]['born']) == priority]
            else:
                allowed = []
            actual = self.q.claim(op['duration'])
            if actual is None:
                assert not allowed, 'missed ready task'
                chosen = None
            else:
                chosen = next(x for x, ident in self.ids.items() if ident == actual['id'])
                assert chosen in allowed, 'claimed ineligible/out-of-order task'
                if chosen in self.tokens:
                    self.old_tokens.append((chosen, self.tokens[chosen]))
                token = actual['lease_token']
                assert token and token not in self.seen_tokens, 'lease token reused'
                self.tokens[chosen] = token
                self.seen_tokens.add(token)
            m.claim(chosen, op['duration'])
        elif kind in ('succeed', 'fail'):
            token = self.tokens[label]
            getattr(self.q, kind)(self.ids[label], token, op['value'])
            m.finish(label, kind == 'succeed', op['value'])
            self.old_tokens.append((label, token))
        elif kind == 'cancel':
            assert self.q.cancel(self.ids[label]), 'cancel did not change active job'
            m.cancel(label)
            if label in self.tokens:
                self.old_tokens.append((label, self.tokens[label]))
        elif kind == 'heartbeat':
            self.q.heartbeat(self.ids[label], self.tokens[label], op['duration'])
            m.heartbeat(label, op['duration'])
        elif kind == 'advance':
            assert op['to'] != m.now
            m.now = op['to']
        elif kind == 'reopen':
            self.q.close()
            self.q = Queue(self.path, clock=lambda: m.now)
        else:
            raise AssertionError('unknown operation')
        self.counts[kind] += 1
        self.check()
        # Extra rejection probes are NOT included in the 300 effective operations.
        if self.old_tokens:
            stale_label, token = self.old_tokens[-1]
            job = m.jobs[stale_label]
            if job['state'] != 'running' or token != self.tokens[stale_label]:
                for action in (self.q.succeed, self.q.fail, self.q.heartbeat):
                    try:
                        action(self.ids[stale_label], token)
                    except TypeError:
                        # fail requires an error argument.
                        try:
                            action(self.ids[stale_label], token, 'stale')
                        except LeaseLost:
                            pass
                        else:
                            raise AssertionError('stale failure accepted')
                    except LeaseLost:
                        pass
                    else:
                        raise AssertionError('stale lease accepted')
                    self.probes += 1
                self.check()

    def generate(self, rng, step):
        m = self.model
        live = m.live()
        active = [x for x, j in m.jobs.items() if j['state'] in ('pending', 'running')]
        choices = ['submit', 'submit', 'advance', 'reopen']
        if m.eligible():
            choices += ['claim'] * 4
        if live:
            choices += ['succeed', 'fail', 'fail', 'heartbeat']
        if active:
            choices += ['cancel']
        kind = rng.choice(choices)
        if kind == 'submit':
            return dict(op=kind, label='j' + str(step), payload={'n': rng.randrange(100), 'text': '载荷'},
                        key=None if rng.random() < .8 else 'k' + str(rng.randrange(5)),
                        limit=rng.randint(1, 4), backoff=rng.choice([1, 2, 4]),
                        due=m.now + rng.choice([0, 0, 1, 5]))
        if kind == 'advance':
            boundaries = [j['ready'] for j in m.jobs.values() if j['state'] == 'pending']
            boundaries += [m.jobs[x]['history'][-1]['end'] for x in live]
            options = [m.now + rng.choice([1, 2, 5, 10, -1])]
            options += [t for b in boundaries for t in (b - .25, b, b + .25) if t != m.now]
            return dict(op=kind, to=rng.choice(options))
        if kind == 'claim':
            return dict(op=kind, duration=rng.choice([2, 5, 10]))
        if kind == 'reopen':
            return dict(op=kind)
        label = rng.choice(active if kind == 'cancel' else live)
        if kind == 'heartbeat':
            # Guarantee an extension, not a no-op, including after clock rollback.
            end = m.jobs[label]['history'][-1]['end']
            return dict(op=kind, label=label, duration=end - m.now + rng.randint(1, 5))
        return dict(op=kind, label=label, value={'answer': step} if kind == 'succeed' else 'error-' + str(step))


def run_seed(seed, operations=None):
    ARTIFACTS.mkdir(parents=True, exist_ok=True)
    rng = random.Random(seed)
    trace = []
    begin = time.monotonic()
    with tempfile.TemporaryDirectory(dir=ROOT) as folder:
        runner = Runner(str(Path(folder) / 'queue.db'))
        try:
            for step in range(len(operations) if operations is not None else 300):
                op = operations[step] if operations is not None else runner.generate(rng, step)
                trace.append(op)
                runner.apply(op)
            assert all(runner.counts[k] > 0 for k in
                       ('submit', 'claim', 'succeed', 'fail', 'cancel', 'heartbeat', 'advance', 'reopen'))
        except BaseException as exc:
            failure = dict(seed=seed, step=len(trace), operations=trace, error=repr(exc))
            # Exclusive creation preserves the first failing prefix before any fix.
            path = ARTIFACTS / ('failure-seed-%d.json' % seed)
            if not path.exists():
                with path.open('x', encoding='utf-8') as stream:
                    json.dump(failure, stream, ensure_ascii=False, indent=2)
            raise
        finally:
            runner.q.close()
        receipt = dict(seed=seed, operations=len(trace), counts=dict(runner.counts),
                       rejection_probes=runner.probes, jobs=len(runner.model.jobs),
                       elapsed_seconds=time.monotonic() - begin, status='passed',
                       trace_sha256=hashlib.sha256(json.dumps(trace, sort_keys=True).encode()).hexdigest())
        (ARTIFACTS / ('seed-%d.json' % seed)).write_text(
            json.dumps(dict(receipt=receipt, operations=trace), ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        return receipt


class ReferenceTests(unittest.TestCase):
    def test_twenty_seeds_three_hundred_operations(self):
        receipts = []
        for seed in range(20):
            with self.subTest(seed=seed):
                receipts.append(run_seed(seed))
        self.assertEqual(len(receipts), 20)
        (ARTIFACTS / 'summary.json').write_text(json.dumps(receipts, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--seed', type=int, default=0)
    parser.add_argument('--replay', type=Path)
    args = parser.parse_args()
    if args.replay:
        data = json.loads(args.replay.read_text(encoding='utf-8'))
        seed = data.get('seed', data.get('receipt', {}).get('seed'))
        print(json.dumps(run_seed(seed, data['operations']), indent=2))
    else:
        print(json.dumps(run_seed(args.seed), indent=2))
